#include "TestSupport.h"
#include "DspController.h"
#include "DspSessionDiscovery.h"
#include <QCoreApplication>
#include <QTemporaryDir>
#include <limits>
int main(int argc,char** argv){QCoreApplication app(argc,argv);QTemporaryDir tmp;auto root=std::filesystem::path(tmp.path().toStdWString());auto s=session(1);StageBusWin32 source,consumer;DspController controller;std::string error;CenterSettings settings;settings.values[0]=0;CHECK(controller.configureCenter(CENTER_MODULE_ROOT,settings,error));CHECK(source.create(s,error));CHECK(DspSessionDiscovery::write(root/"source.json",s,"EXTERNAL",error));CHECK(controller.start(root,root/"source.json",error));auto deadline=qpc()+frequency()*2;while(!controller.snapshot().diag.center.loaded){CHECK(qpc()<deadline && controller.snapshot().state!=DspStateCode::Fault);source.heartbeat(qpc());Sleep(1);}CHECK(consumer.open(controller.snapshot().outputSession,error));Planes<10> in;Planes<11> out;in.data[0].fill(.25);in.data[1].fill(.25);for(uint64_t seq=1;seq<=12;seq++){if(seq==4){settings.values[15]=0;CHECK(controller.requestCenter(settings));}if(seq==8){settings.values[15]=1;CHECK(controller.requestCenter(settings));}if(seq==4||seq==8){auto revision=seq==4?2u:3u;deadline=qpc()+frequency();while(controller.snapshot().diag.center.revision<revision){CHECK(qpc()<deadline);source.heartbeat(qpc());consumer.heartbeat(qpc());Sleep(1);}}CHECK(consumer.trySendRequest(request(s,seq))==StageBusIoResult::Ok);StageBusFrameRequest req{};deadline=qpc()+frequency();while(source.tryReceiveRequest(req)==StageBusIoResult::Empty){CHECK(qpc()<deadline);source.heartbeat(qpc());consumer.heartbeat(qpc());Sleep(1);}auto b=header(req);CHECK(source.tryPublish(b,in.in.data())==StageBusIoResult::Ok);StageBusBlockHeader result{};while(consumer.tryConsume(result,out.out.data())==StageBusIoResult::Empty){CHECK(qpc()<deadline);source.heartbeat(qpc());consumer.heartbeat(qpc());Sleep(1);}for(auto v:out.data[2])CHECK(v==(seq>=4 && seq<8?0:.25));CHECK(!std::memcmp(in.in[0],out.in[0],8192));CHECK(!std::memcmp(in.in[1],out.in[1],8192));}
// Invalid programme input faults the native module, unloads on its worker and
// publishes cleared ownership immediately, without needing GUI shutdown.
CHECK(consumer.trySendRequest(request(s,13))==StageBusIoResult::Ok);StageBusFrameRequest req{};deadline=qpc()+frequency();while(source.tryReceiveRequest(req)==StageBusIoResult::Empty){CHECK(qpc()<deadline);source.heartbeat(qpc());consumer.heartbeat(qpc());Sleep(1);}in.data[0][0]=std::numeric_limits<double>::infinity();auto b=header(req);CHECK(source.tryPublish(b,in.in.data())==StageBusIoResult::Ok);
while(controller.snapshot().state!=DspStateCode::Fault || controller.snapshot().diag.center.loaded){CHECK(qpc()<deadline);Sleep(1);}CHECK(!controller.snapshot().diag.center.latencyValid);controller.stop();CHECK(controller.snapshot().state==DspStateCode::Fault);std::cout<<"PASS worker-owned native Center, bounded UI command adoption on block boundary, enable toggles affect only C, LR remains exact\n";}
